import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { DatabaseSync } from 'node:sqlite';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import fixture from 'src/library-import/fixtures/photoprism/261029-sqlite.json' with { type: 'json' };
import { openPhotoprismSnapshot } from 'src/library-import/photoprism.js';

// Recreate the exact structure generated by the pinned application's own migrations, not a hand-written schema.
describe('PhotoPrism pinned SQLite extraction', () => {
  let root: string;
  let path: string;
  let database: DatabaseSync;
  beforeEach(async () => {
    root = await mkdtemp(join(tmpdir(), 'frameleaf-photoprism-'));
    path = join(root, 'source.sqlite');
    database = new DatabaseSync(path);
    for (const type of ['table', 'index', 'trigger', 'view']) {
      for (const object of fixture.objects) {
        if (object.type === type && object.sql && !object.name.startsWith('sqlite_')) database.exec(object.sql);
      }
    }
    for (const migration of fixture.migrations) {
      database
        .prepare('INSERT INTO migrations(id,dialect,stage,error,finished_at) VALUES(?,?,?,?,?)')
        .run(migration.id, migration.dialect, migration.stage, '', '2026-11-01T00:00:00Z');
    }
    database
      .prepare('INSERT INTO versions(version,error,migrated_at) VALUES(?,?,?)')
      .run(fixture.source.executableVersion, '', '2026-11-01T00:00:00Z');
    database.exec(
      "INSERT INTO auth_users (user_uid,user_name,display_name,user_role,can_login,reset_token) VALUES ('u-fixture','fixture','Fixture Owner','admin',1,'must-never-export'); INSERT INTO photos (photo_uid,created_by,photo_title,photo_caption,photo_private,photo_favorite) VALUES ('p-fixture','u-fixture','Edited title','Manual caption',1,1); INSERT INTO files (file_uid,photo_uid,file_name,file_root,file_primary,file_sidecar,file_size) VALUES ('f-fixture','p-fixture','owner-a/blue.png','/',1,0,1948)",
    );
  });
  afterEach(async () => {
    database.close();
    await rm(root, { recursive: true, force: true });
  });
  it('reads all photo and original metadata without transferring account secrets', () => {
    const source = openPhotoprismSnapshot(path, fixture.source.version);
    const photos = [...source.rows('photos')].flat();
    const files = [...source.rows('files')].flat();
    const users = [...source.rows('users')].flat();
    source.close();
    expect(photos[0].photo_caption).toBe('Manual caption');
    expect(photos[0].photo_private).toBe(1n);
    expect(files[0].file_name).toBe('owner-a/blue.png');
    expect(users[0].user_uid).toBe('u-fixture');
    expect(users[0]).not.toHaveProperty('reset_token');
    expect(() => [...source.rows('passwords' as never)]).toThrow('PHOTOPRISM_TABLE_NOT_ALLOWED');
    expect(() => [...source.rows('auth_sessions' as never)]).toThrow('PHOTOPRISM_TABLE_NOT_ALLOWED');
  });
  it('refuses schema drift before extracting content', () => {
    database.exec('ALTER TABLE photos ADD COLUMN unexpected_private_state TEXT');
    expect(() => openPhotoprismSnapshot(path, fixture.source.version)).toThrow('PHOTOPRISM_SCHEMA_UNQUALIFIED');
  });
  it('refuses unqualified versions', () => {
    expect(() => openPhotoprismSnapshot(path, 'unknown-release')).toThrow('PHOTOPRISM_VERSION_UNQUALIFIED');
  });
  it('preserves large source integer identities without Number conversion', () => {
    database.exec("UPDATE photos SET id=9007199254740993 WHERE photo_uid='p-fixture'");
    const source = openPhotoprismSnapshot(path, fixture.source.version);
    try {
      expect([...source.rows('photos')].flat()[0].id).toBe(9_007_199_254_740_993n);
    } finally {
      source.close();
    }
  });
  it('bounds batches and includes negative row identities', () => {
    database.exec(
      "INSERT INTO photos (id,photo_uid) VALUES(-1,'negative'); WITH RECURSIVE seq(n) AS (SELECT 1 UNION ALL SELECT n+1 FROM seq WHERE n<2100) INSERT INTO photos(photo_uid) SELECT 'p-'||n FROM seq",
    );
    const source = openPhotoprismSnapshot(path, fixture.source.version);
    try {
      const batches = [...source.rows('photos')];
      expect(batches.map((batch) => batch.length)).toEqual([1000, 1000, 102]);
      expect(batches[0][0].id).toBe(-1n);
    } finally {
      source.close();
    }
  });
  it('refuses failed or missing migrations even when the catalog still matches', () => {
    database.exec("UPDATE migrations SET error='synthetic failure' WHERE id=(SELECT min(id) FROM migrations)");
    expect(() => openPhotoprismSnapshot(path, fixture.source.version)).toThrow('PHOTOPRISM_MIGRATIONS_INCOMPLETE');
    database.exec('DELETE FROM migrations');
    expect(() => openPhotoprismSnapshot(path, fixture.source.version)).toThrow('PHOTOPRISM_MIGRATIONS_INCOMPLETE');
  });
  it('accepts successful historical migration entries while refusing failed historical entries', () => {
    database
      .prepare('INSERT INTO migrations(id,error,finished_at) VALUES(?,?,?)')
      .run('historical-id', '', '2026-11-01T00:00:00Z');
    const source = openPhotoprismSnapshot(path, fixture.source.version);
    source.close();
    database.prepare('UPDATE migrations SET error=? WHERE id=?').run('failure', 'historical-id');
    expect(() => openPhotoprismSnapshot(path, fixture.source.version)).toThrow('PHOTOPRISM_MIGRATIONS_INCOMPLETE');
  });
  it.each([
    ['required', null],
    ['required', '0001-01-01T00:00:00Z'],
    ['historical', null],
    ['historical', '0001-01-01T00:00:00Z'],
  ])('refuses unfinished %s migration timestamps %s', (kind, finishedAt) => {
    if (kind === 'required')
      database.prepare('UPDATE migrations SET finished_at=? WHERE id=(SELECT min(id) FROM migrations)').run(finishedAt);
    else
      database
        .prepare('INSERT INTO migrations(id,error,finished_at) VALUES(?,?,?)')
        .run('historical-pending', '', finishedAt);
    expect(() => openPhotoprismSnapshot(path, fixture.source.version)).toThrow('PHOTOPRISM_MIGRATIONS_INCOMPLETE');
  });
});
